"""One-shot investigation: sampling funnel + metrics breakdown for paper_run."""
from __future__ import annotations

import json
import sqlite3
from collections import Counter, defaultdict
from datetime import datetime, timedelta, timezone
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DB = ROOT / ".local_paper_console.db"
RUN = "78ba69a7-2bfb-457e-9a97-934aaf418e00"


def _parse_details(raw):
    if raw is None:
        return {}
    if isinstance(raw, dict):
        return raw
    try:
        return json.loads(raw)
    except (TypeError, json.JSONDecodeError):
        return {}


def main() -> None:
    conn = sqlite3.connect(str(DB))
    conn.row_factory = sqlite3.Row
    now = datetime.now(timezone.utc)
    cut48 = (now - timedelta(hours=48)).isoformat()
    cut24 = (now - timedelta(hours=24)).isoformat()

    print("=== reason_code counts 48h ===")
    rows = conn.execute(
        """
        SELECT reason_code, COUNT(*) AS n
        FROM decision_funnel_terminals
        WHERE paper_run_id=? AND created_at >= ?
        GROUP BY reason_code
        ORDER BY n DESC
        """,
        (RUN, cut48),
    ).fetchall()
    for r in rows:
        print(dict(r))

    print("\n=== reason_code counts 24h ===")
    for r in conn.execute(
        """
        SELECT reason_code, COUNT(*) AS n
        FROM decision_funnel_terminals
        WHERE paper_run_id=? AND created_at >= ?
        GROUP BY reason_code
        ORDER BY n DESC
        """,
        (RUN, cut24),
    ):
        print(dict(r))

    print("\n=== primary reason vs sampling (from details) last 48h ===")
    primary_reasons = Counter()
    sampling_attempted = Counter()
    ineligible = Counter()
    component = {
        "close_gt_ema50": 0,
        "close_lt_ema50": 0,
        "macd_gt_0": 0,
        "macd_lt_0": 0,
        "rsi_long_band": 0,
        "rsi_short_band": 0,
        "long_all": 0,
        "short_all": 0,
        "atr_ok": 0,
        "rows_with_metrics": 0,
    }
    per_symbol_component = defaultdict(lambda: Counter())
    recent_metrics = []
    aligned_hist = []

    cols = [r[1] for r in conn.execute("PRAGMA table_info(decision_funnel_terminals)")]
    print("funnel_cols", cols)

    detail_col = "details" if "details" in cols else None
    if detail_col is None:
        for c in cols:
            if "detail" in c.lower() or "payload" in c.lower() or "trace" in c.lower():
                detail_col = c
                break
    print("using_detail_col", detail_col)

    q = f"""
        SELECT symbol, bar_time, reason_code, status, created_at, {detail_col or "NULL AS details"}
        FROM decision_funnel_terminals
        WHERE paper_run_id=? AND created_at >= ?
        ORDER BY created_at DESC
    """
    for row in conn.execute(q, (RUN, cut48)):
        d = _parse_details(row["details"] if detail_col else None)
        # nested traces common
        trace = d.get("decision_trace") or d.get("trace") or d
        metrics = (
            trace.get("sampling_metrics")
            or d.get("sampling_metrics")
            or (d.get("details") or {}).get("sampling_metrics")
            if isinstance(d.get("details"), dict)
            else None
        )
        if metrics is None and isinstance(trace, dict):
            metrics = trace.get("sampling_metrics")
        primary = (
            d.get("primary_reason")
            or trace.get("primary_reason")
            or d.get("reason")
            or trace.get("pipeline_status")
            or d.get("decision_reason")
        )
        # also look in nested
        if primary is None:
            primary = d.get("action_reason") or d.get("signal_reason")
        if primary:
            primary_reasons[str(primary)] += 1
        samp_rej = (
            trace.get("sampling_fallback_rejection_reason")
            if isinstance(trace, dict)
            else None
        ) or d.get("sampling_fallback_rejection_reason")
        if samp_rej:
            sampling_attempted[str(samp_rej)] += 1
        inelig = d.get("sampling_ineligibility_reason") or (
            trace.get("sampling_ineligibility_reason") if isinstance(trace, dict) else None
        )
        if inelig:
            ineligible[str(inelig)] += 1

        if isinstance(metrics, dict) and "close" in metrics:
            component["rows_with_metrics"] += 1
            close = float(metrics["close"])
            ema50 = float(metrics["ema50"])
            macd = float(metrics["macd_histogram"])
            rsi = float(metrics["rsi14"])
            atr = metrics.get("atr14")
            atr_ok = atr is not None and float(atr) > 0
            if atr_ok:
                component["atr_ok"] += 1
            if close > ema50:
                component["close_gt_ema50"] += 1
            if close < ema50:
                component["close_lt_ema50"] += 1
            if macd > 0:
                component["macd_gt_0"] += 1
            if macd < 0:
                component["macd_lt_0"] += 1
            if 50 <= rsi <= 72:
                component["rsi_long_band"] += 1
            if 28 <= rsi <= 50:
                component["rsi_short_band"] += 1
            long_ok = close > ema50 and macd > 0 and 50 <= rsi <= 72 and atr_ok
            short_ok = close < ema50 and macd < 0 and 28 <= rsi <= 50 and atr_ok
            if long_ok:
                component["long_all"] += 1
            if short_ok:
                component["short_all"] += 1
            sym = row["symbol"]
            per_symbol_component[sym]["n"] += 1
            if close > ema50:
                per_symbol_component[sym]["close_gt_ema50"] += 1
            if close < ema50:
                per_symbol_component[sym]["close_lt_ema50"] += 1
            if macd > 0:
                per_symbol_component[sym]["macd_gt_0"] += 1
            if macd < 0:
                per_symbol_component[sym]["macd_lt_0"] += 1
            if 50 <= rsi <= 72:
                per_symbol_component[sym]["rsi_long"] += 1
            if 28 <= rsi <= 50:
                per_symbol_component[sym]["rsi_short"] += 1
            if long_ok or short_ok:
                aligned_hist.append(
                    {
                        "symbol": sym,
                        "bar_time": row["bar_time"],
                        "created_at": row["created_at"],
                        "reason_code": row["reason_code"],
                        "metrics": metrics,
                        "dir": "LONG" if long_ok else "SHORT",
                    }
                )
            if len(recent_metrics) < 12:
                recent_metrics.append(
                    {
                        "symbol": sym,
                        "bar_time": row["bar_time"],
                        "created_at": row["created_at"],
                        "reason_code": row["reason_code"],
                        "close": close,
                        "ema50": ema50,
                        "macd": macd,
                        "rsi": rsi,
                        "atr": atr,
                        "close_vs_ema": "above" if close > ema50 else "below",
                        "macd_sign": "pos" if macd > 0 else "neg",
                        "rsi_band": (
                            "long"
                            if 50 <= rsi <= 72
                            else ("short" if 28 <= rsi <= 50 else "out")
                        ),
                    }
                )

    print("primary_reasons", primary_reasons.most_common(20))
    print("sampling_rejection", sampling_attempted.most_common(20))
    print("ineligible", ineligible.most_common(20))
    print("component_counts", component)
    print("per_symbol", {k: dict(v) for k, v in per_symbol_component.items()})
    print("\n=== recent metrics (up to 12) ===")
    for m in recent_metrics:
        print(m)
    print("\n=== funnel rows where metrics WERE aligned (should be rare if always NOT_ALIGNED) ===")
    for a in aligned_hist[:20]:
        print(a)

    print("\n=== TESTNET_SAMPLING_SIGNAL / PRETRADE history ===")
    for r in conn.execute(
        """
        SELECT symbol, bar_time, reason_code, status, created_at, substr(cast(details as text),1,500) AS d
        FROM decision_funnel_terminals
        WHERE paper_run_id=?
          AND (reason_code LIKE '%SAMPLING%' OR reason_code LIKE '%PRETRADE%' OR reason_code LIKE '%TESTNET%')
        ORDER BY created_at DESC LIMIT 40
        """,
        (RUN,),
    ):
        print(dict(r))

    print("\n=== Jul 27 sampling successes (any run) ===")
    for r in conn.execute(
        """
        SELECT symbol, bar_time, reason_code, status, created_at, paper_run_id,
               substr(cast(details as text),1,800) AS d
        FROM decision_funnel_terminals
        WHERE created_at LIKE '2026-07-27%'
          AND (reason_code LIKE '%TESTNET_SAMPLING%' OR cast(details as text) LIKE '%testnet_sampling%'
               OR cast(details as text) LIKE '%sampling_metrics%')
        ORDER BY created_at DESC LIMIT 30
        """
    ):
        print(dict(r))

    print("\n=== ohlcv freshness ===")
    for r in conn.execute(
        """
        SELECT symbol, timeframe, COUNT(*) AS n,
               MIN(timestamp) AS min_ts, MAX(timestamp) AS max_ts
        FROM ohlcv_bars
        WHERE symbol IN ('BTC/USDT','ETH/USDT') AND timeframe='15m'
        GROUP BY symbol, timeframe
        """
    ):
        print(dict(r))

    print("\n=== open positions / orders for run ===")
    tables = [r[0] for r in conn.execute("SELECT name FROM sqlite_master WHERE type='table'")]
    for t in ("paper_positions", "positions", "order_executions", "orders"):
        if t not in tables:
            continue
        cols = [r[1] for r in conn.execute(f"PRAGMA table_info({t})")]
        print(t, "cols_sample", cols[:20])
        if "paper_run_id" in cols:
            q2 = f"SELECT * FROM {t} WHERE paper_run_id=? ORDER BY rowid DESC LIMIT 8"
            try:
                for r in conn.execute(q2, (RUN,)):
                    d = dict(r)
                    # trim
                    for k, v in list(d.items()):
                        if isinstance(v, str) and len(v) > 200:
                            d[k] = v[:200]
                    print(t, d)
            except Exception as e:
                print(t, "err", e)

    # paper_run profile
    print("\n=== paper_run profile ===")
    for r in conn.execute(
        "SELECT paper_run_id, status, created_at, execution_profile, paper_metrics_summary FROM paper_runs WHERE paper_run_id=?",
        (RUN,),
    ):
        d = dict(r)
        for k in ("execution_profile", "paper_metrics_summary"):
            if d.get(k):
                try:
                    d[k] = json.loads(d[k])
                except Exception:
                    pass
        print("status", d.get("status"), "created", d.get("created_at"))
        ep = d.get("execution_profile") or {}
        print(
            "profile_keys",
            {
                k: ep.get(k)
                for k in (
                    "simulation_sampling_fallback_enabled",
                    "execution_mode",
                    "mirror_to_gateway",
                    "cost_gate_verified",
                    "strategy_lane",
                    "acceptance_symbols",
                    "acceptance_scope_hash",
                )
            },
        )
        pm = d.get("paper_metrics_summary") or {}
        print(
            "metrics_sample",
            {
                k: pm.get(k)
                for k in pm
                if "sampl" in k.lower() or "cool" in k.lower() or "rate" in k.lower()
            },
        )

    conn.close()


if __name__ == "__main__":
    main()
